    for (const s of segments) pts.push([s.from[0], s.from[1]], [s.to[0], s.to[1]]);
    if (turtle) pts.push([turtle.pos[0], turtle.pos[1]]);
    let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
    for (const [x, y] of pts) {
      x0 = Math.min(x0, x);
      x1 = Math.max(x1, x);
      y0 = Math.min(y0, y);
      y1 = Math.max(y1, y);
