/** Steps per second for the speed slider; the last position runs without animation. */
const tempoRate = (v: number) => (v >= TEMPO_MAX ? Infinity : 2 ** v);
const tempoLabel = (v: number) => (v >= TEMPO_MAX ? 'natychmiast' : `${2 ** v} krok/s`);

const STUDIO_HTML = `
