  /* ---------- lifecycle ---------- */

  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    this.stopLoop();
    this.flushDraft();
    window.removeEventListener('keydown', this.onKey);
    window.removeEventListener('logomocja:theme', this.onTheme);
    this.viewToken++;
    this.view?.dispose?.();
    this.view = null;
  }

  /** Saves the draft when the page is left or hidden. */
  flushDraft() {
