        `<optgroup label="${m === '2d' ? 'Płaszczyzna 2D' : 'Przestrzeń 3D'}">${EXAMPLES.filter((e) => e.mode === m)
          .map((e) => `<option value="${e.name}">${escapeHtml(e.name)} — ${escapeHtml(e.description)}</option>`)
          .join('')}</optgroup>`,
    );
