  decodeProgram,
  getThemeChoice,
  parseHash,
  parseMode,
  storageGet,
  storageSet,
  THEME_LABEL,
  type ThemeChoice,
} from './ui/util';

const page = document.getElementById('page')!;
let studio: Studio | null = null;
let studioKey = '';
let waiters: ((s: Studio) => void)[] = [];

const LAST_MODE_KEY = 'logomocja.tryb';

