  },
  async open(source, mode) {
    const m: Mode = mode === '3d' ? '3d' : '2d';
    if (!studio) location.hash = '#/';
    const s = await whenStudio();
    return s.openInstant(source, m);
  },
};

// Remember the mode of the studio between visits.
window.addEventListener('logomocja:mode', (e) => storageSet(LAST_MODE_KEY, (e as CustomEvent<string>).detail));

export { CHALLENGES };
