.editor { display: flex; width: 100%; height: 100%; min-height: 0; position: absolute; inset: 0; }
.gutter {
  flex: 0 0 auto;
  min-width: 3.4em;
  padding: 12px 8px 12px 0;
  text-align: right;
  color: var(--muted);
  background: var(--surface-2);
  border-right: 1px solid var(--border);
  font: 14px/22px var(--mono);
  overflow: hidden;
  user-select: none;
}
.gn { height: 22px; padding-right: 2px; }
.gn.exec { color: var(--accent); font-weight: 700; background: var(--exec-bg); }
.gn.err { color: var(--danger); font-weight: 700; }

.code { position: relative; flex: 1; min-width: 0; background: var(--code-bg); }
.code-overlay,
.code-input {
  position: absolute;
  inset: 0;
  margin: 0;
  padding: 12px 12px 40vh 12px;
  font: 14px/22px var(--mono);
  white-space: pre;
  tab-size: 2;
  border: 0;
  overflow: hidden;
  word-wrap: normal;
