.code-overlay { color: var(--name); pointer-events: none; }
.code-input {
  background: transparent;
  color: transparent;
  caret-color: var(--text);
  resize: none;
  outline: none;
  overflow: auto;
  z-index: 1;
  -webkit-text-fill-color: transparent;
}
.code-input:focus-visible { outline: 3px solid var(--focus); outline-offset: -3px; }
.code-input::selection { background: rgb(127 160 230 / 0.35); -webkit-text-fill-color: transparent; }
.ln { height: 22px; min-width: 100%; width: max-content; }
.ln.exec { background: var(--exec-bg); }
.ln.err-line { background: var(--danger-bg); }
.kw { color: var(--kw); font-weight: 650; }
.name { color: var(--name); }
.num { color: var(--num); }
.str { color: var(--str); }
.com { color: var(--com); font-style: italic; }
.op { color: var(--op); }
.br { color: var(--br); font-weight: 650; }
.err-char {
  text-decoration: underline wavy var(--danger);
  text-decoration-thickness: 2px;
  background: rgb(180 35 24 / 0.14);
  border-radius: 2px;
}
.err-char.eol { display: inline-block; width: 0.6em; background: rgb(180 35 24 / 0.3); }

.messages { padding: 8px 12px; border-top: 1px solid var(--border); min-height: 3.2em; }
.messages p { margin: 0; font-size: 14px; }
.status { color: var(--muted); }
.error { color: var(--danger); font-weight: 600; display: none; }
.error.visible { display: block; }

.challenge {
  border-top: 1px solid var(--border);
  padding: 12px;
  max-height: 46vh;
  overflow: auto;
  background: var(--surface-2);
}
.challenge .task { font-size: 15px; }
.challenge .reqs { margin: 0 0 8px; padding-left: 20px; color: var(--muted); font-size: 14px; }
.verdict { margin: 10px 0; font-weight: 600; min-height: 1.5em; }
.verdict.pass { color: var(--ok); }
.verdict.fail { color: var(--danger); }
.badge {
  display: inline-block;
  font-size: 12px;
  font-weight: 650;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  border: 1px solid var(--border);
  vertical-align: middle;
}
.badge.ok { background: var(--ok-bg); color: var(--ok); border-color: transparent; }

.pane-view .toolbar { border-bottom: 1px solid var(--border); }
.view-host {
  flex: 1;
  min-height: 300px;
  position: relative;
  background: var(--canvas-bg);
  overflow: hidden;
}
.view-canvas {
  position: absolute;
  inset: 0;
  display: block;
  touch-action: none;
  cursor: grab;
  outline-offset: -3px;
}
.view-canvas:active { cursor: grabbing; }
.view-note { margin: 0; padding: 8px 12px; font-size: 14px; color: var(--danger); min-height: 0; }
.view-note:empty { display: none; }

/* ---------- pages ---------- */
.page-wrap, main#page > section { max-width: 1100px; }
main#page {
  padding: 20px clamp(12px, 3vw, 32px) 40px;
  max-width: 1200px;
  width: 100%;
  margin: 0 auto;
}
main#page > h1 { margin-top: 8px; }
.lead { color: var(--muted); max-width: 70ch; }
.cards { display: grid; gap: 12px; grid-template-columns: repeat(auto-fill, minmax(min(100%, 300px), 1fr)); }
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.card header { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.card .actions { margin-top: auto; }
.card details summary { cursor: pointer; color: var(--muted); padding: 6px 0; }
.challenge-list { list-style: none; padding: 0; margin: 0; display: grid; gap: 12px; }
.challenge-list .card.row { flex-direction: row; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.challenge-list .card.row > div:first-child { flex: 1 1 320px; }
.row-end { display: flex; align-items: center; gap: 10px; }
.meta { color: var(--muted); font-size: 13px; margin: 0; }
.toc { display: flex; flex-wrap: wrap; gap: 8px; margin: 12px 0 20px; }
.toc a {
  padding: 6px 10px; border-radius: 8px; border: 1px solid var(--border);
  text-decoration: none; background: var(--surface); color: var(--text); font-size: 14px; min-height: 40px;
  display: inline-flex; align-items: center;
}
main#page section { margin-top: 28px; scroll-margin-top: 72px; }
main#page section > ul { padding-left: 20px; }
main#page section > ul li { margin-bottom: 6px; }
main#page .card h3 code { font-size: 1em; }

.footer {
  padding: 16px;
  color: var(--muted);
  font-size: 13px;
  text-align: center;
  border-top: 1px solid var(--border);
}

/* ---------- small screens ---------- */
@media (max-width: 959px) {
  .studio {
    grid-template-columns: 1fr;
    height: auto;
    min-height: 0;
  }
  .editor-host { min-height: 52vh; }
  .view-host { min-height: 52vh; flex: none; height: 52vh; }
  .pane-view { order: -1; }
  .challenge { max-height: none; }
  .code-overlay, .code-input { padding-bottom: 12px; }
}

@media (max-width: 600px) {
  .topbar { gap: 8px; padding: 8px 10px; }
  .topbar nav a { padding: 6px 8px; }
  .top-actions { width: 100%; margin-left: 0; }
  .top-actions .btn { flex: 1; }
  .toolbar .btn { flex: 1 1 auto; }
  label.tempo { width: 100%; }
  label.tempo input { flex: 1; }
  .gutter { min-width: 2.6em; }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; transition: none !important; }
}
